#!/usr/bin/env bash
# Builds k8s/observability/config/dashboard-configmaps.yaml from the dashboard
# JSON sources in k8s/observability/dashboards/.
#
# Run this after editing any dashboard, then commit the regenerated file:
#   ./scripts/build-dashboards.sh
#
# The ConfigMaps carry label grafana_dashboard=1, which the
# kube-prometheus-stack Grafana sidecar watches (searchNamespace: ALL).
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DASH_DIR="${REPO_ROOT}/k8s/observability/dashboards"
OUT="${REPO_ROOT}/k8s/observability/config/dashboard-configmaps.yaml"

python3 - "$DASH_DIR" "$OUT" <<'EOF'
import json, sys, os

dash_dir, out = sys.argv[1], sys.argv[2]
os.makedirs(os.path.dirname(out), exist_ok=True)
allowed_uids = {"prometheus", "loki", "tempo", "alertmanager"}

docs = []
for fname in sorted(os.listdir(dash_dir)):
    if not fname.endswith(".json"):
        continue
    path = os.path.join(dash_dir, fname)
    with open(path) as f:
        try:
            d = json.load(f)
        except json.JSONDecodeError as e:
            sys.exit(f"INVALID JSON in {fname}: {e}")
    # --- structural validation ---
    for field in ("title", "uid", "panels"):
        assert field in d, f"{fname}: missing required field {field!r}"
    assert isinstance(d["panels"], list) and d["panels"], f"{fname}: no panels"
    for p in d["panels"]:
        assert "title" in p and "targets" in p, f"{fname}: panel missing title/targets"
        panel_uid = (p.get("datasource") or {}).get("uid")
        for t in p["targets"]:
            assert "expr" in t and t["expr"].strip(), f"{fname}: empty expr in panel {p['title']!r}"
            uid = (t.get("datasource") or {}).get("uid") or panel_uid
            assert uid in allowed_uids, f"{fname}: bad datasource uid {uid!r} in panel {p['title']!r}"
    name = fname[:-len(".json")]
    print(f"  ok: {fname} ({len(d['panels'])} panels, uid={d['uid']})")
    with open(path) as f:
        raw = f.read()
    indented = "\n".join("    " + line if line.strip() else "" for line in raw.splitlines())
    docs.append(f"""apiVersion: v1
kind: ConfigMap
metadata:
  name: {name}
  namespace: monitoring
  labels:
    app.kubernetes.io/part-of: shipit
    grafana_dashboard: "1"
data:
  {fname}: |
{indented}
""")

with open(out, "w") as f:
    f.write("# GENERATED by scripts/build-dashboards.sh — do not edit by hand.\n")
    f.write("# Source: k8s/observability/dashboards/*.json\n---\n")
    f.write("---\n".join(docs))
print(f"wrote {out} ({len(docs)} dashboards)")
EOF
